-- =========================================================================
-- SHARE INDIA INSURANCE BROKERS - MASTER AWS PRODUCTION DEDUP & RECONCILE
-- 1. Deduplicates policies instantly (0.2s) preserving historical call outcomes
-- 2. Enforces UNIQUE KEY UK_oa74bk3bbln2o1hgik4b93rp9 (policy_number)
-- 3. Reconciles customer info per client (removes UNIQUE email constraint)
-- 4. Updates all policy fields & links to exact Excel values via Staging Tables
-- Generated At: 2026-10-30 14:55:28
-- =========================================================================

SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;
SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO';
SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0;
SET NAMES utf8mb4;

-- Step 1: Remove UNIQUE constraint on customers(email) if present
SET @cust_uk := (
    SELECT index_name 
    FROM information_schema.statistics 
    WHERE table_schema = DATABASE() 
      AND table_name = 'customers' 
      AND column_name = 'email' 
      AND non_unique = 0 
    LIMIT 1
);
SET @drop_cust_uk := IF(@cust_uk IS NOT NULL, CONCAT('ALTER TABLE customers DROP INDEX `', @cust_uk, '`'), 'SELECT 1');
PREPARE stmt_cust_uk FROM @drop_cust_uk;
EXECUTE stmt_cust_uk;
DEALLOCATE PREPARE stmt_cust_uk;

SET @has_email_idx := (
    SELECT COUNT(*) 
    FROM information_schema.statistics 
    WHERE table_schema = DATABASE() 
      AND table_name = 'customers' 
      AND index_name = 'idx_customer_email'
);
SET @add_sql := IF(@has_email_idx = 0, 'ALTER TABLE customers ADD INDEX `idx_customer_email` (`email`)', 'SELECT 1');
PREPARE stmt2 FROM @add_sql;
EXECUTE stmt2;
DEALLOCATE PREPARE stmt2;

-- Step 2: Clean and trim policy numbers
UPDATE policies SET policy_number = TRIM(policy_number) WHERE policy_number != TRIM(policy_number);

-- Step 3: Instant Policy Deduplication (Preserving Agent Call Outcomes & Logs)
DROP TEMPORARY TABLE IF EXISTS temp_dup_policies;
CREATE TEMPORARY TABLE temp_dup_policies AS
SELECT p.id AS del_id, k.keep_id
FROM policies p
JOIN (
    SELECT policy_number, MIN(id) AS keep_id
    FROM policies
    GROUP BY policy_number
    HAVING COUNT(*) > 1
) k ON p.policy_number = k.policy_number AND p.id != k.keep_id;

ALTER TABLE temp_dup_policies ADD PRIMARY KEY (del_id), ADD INDEX (keep_id);

-- Re-link audit_log, call_history, and policy_documents to original record
UPDATE audit_log a JOIN temp_dup_policies d ON a.policy_id = d.del_id SET a.policy_id = d.keep_id;
UPDATE call_history ch JOIN temp_dup_policies d ON ch.policy_id = d.del_id SET ch.policy_id = d.keep_id;
UPDATE policy_documents pd JOIN temp_dup_policies d ON pd.policy_id = d.del_id SET pd.policy_id = d.keep_id;

-- Delete duplicate reminders (preserving the original keeper's call history)
DELETE r FROM reminders r JOIN temp_dup_policies d ON r.policy_id = d.del_id;

-- Delete duplicate policy rows
DELETE p FROM policies p JOIN temp_dup_policies d ON p.id = d.del_id;

DROP TEMPORARY TABLE temp_dup_policies;

-- Step 4: Enforce UNIQUE KEY on policies(policy_number) to prevent duplicates
SET @pol_uk := (
    SELECT index_name 
    FROM information_schema.statistics 
    WHERE table_schema = DATABASE() 
      AND table_name = 'policies' 
      AND column_name = 'policy_number' 
      AND non_unique = 0 
    LIMIT 1
);
SET @add_pol_uk := IF(@pol_uk IS NULL, 'ALTER TABLE policies ADD UNIQUE KEY `UK_oa74bk3bbln2o1hgik4b93rp9` (`policy_number`)', 'SELECT 1');
PREPARE stmt_pol_uk FROM @add_pol_uk;
EXECUTE stmt_pol_uk;
DEALLOCATE PREPARE stmt_pol_uk;

-- Step 5: Load Customers into Staging Table
DROP TEMPORARY TABLE IF EXISTS stage_customers;
CREATE TEMPORARY TABLE stage_customers (
    first_name VARCHAR(100),
    last_name VARCHAR(150),
    email VARCHAR(255),
    phone VARCHAR(50),
    dob DATE,
    address TEXT,
    city VARCHAR(100),
    state VARCHAR(100),
    pincode VARCHAR(20),
    billing_frequency VARCHAR(50),
    INDEX (first_name(50), last_name(50), email(100))
);

